function ContactPage({ store }) {
  return <div className="customer-page"><CustomerPageHero eyebrow="Find your table" title={<>Come as you are.<br /><em>Stay for dinner.</em></>} text="Questions, group plans or simply a craving? We are one call away." image={imageUrls.friedRice} /><main className="section contact-page"><div className="contact-grid"><div className="contact-panel"><Eyebrow>Say hello</Eyebrow><h2>We would love<br /><em>to hear from you.</em></h2><div className="contact-list"><a href={`tel:${store.settings.phone}`}><span><Icon name="phone" size={18} /></span><div><small>Call the house</small><strong>{store.settings.phone}</strong></div></a><a href={`mailto:${store.settings.email}`}><span>@</span><div><small>Write to us</small><strong>{store.settings.email}</strong></div></a><div><span>⌖</span><div><small>Find us here</small><strong>{store.settings.address}</strong></div></div></div></div><div className="map-card"><div className="map-grid" /><div className="map-pin">✦</div><div className="map-label"><strong>Friends Bawarchi Biryani</strong><span>18 Spice Lane · Jubilee Hills</span></div></div></div><div className="hours-card"><div><Eyebrow>Opening hours</Eyebrow><h3>{store.settings.hours}</h3></div><Link to="/menu" className="button button-dark">Order for pickup <Icon name="arrow" size={16} /></Link></div></main><Footer settings={store.settings} /></div>
}

function CartPage({ cart, store, onUpdateQty, onRemove, onPlaceOrder, cartTotal }) {
  const [form, setForm] = useState({ name: "", phone: "", mode: "Takeaway", payment: "UPI" })
  const [confirmed, setConfirmed] = useState(null)
  const items = cart.map((item) => ({ ...item, dish: store.menu.find((dish) => dish.id === item.id) })).filter((item) => item.dish)
  const submit = (event) => { event.preventDefault(); if (!form.name.trim() || !form.phone.trim() || !items.length) return; const order = onPlaceOrder(form); setConfirmed(order) }
  if (confirmed) return <div className="customer-page"><main className="confirmation"><div className="confirmation-mark"><Icon name="check" size={30} /></div><Eyebrow>Order received · Prototype mode</Eyebrow><h1>See you soon,<br /><em>{form.name.split(" ")[0]}.</em></h1><p>Your sample order <strong>{confirmed.id}</strong> is on the way to the kitchen screen. No payment has been processed.</p><div className="confirmation-card"><span>Order total</span><strong>{money(confirmed.amount)}</strong><span>{form.mode} · {form.payment}</span></div><Link to="/menu" className="button button-dark">Order something else <Icon name="arrow" size={16} /></Link></main><Footer settings={store.settings} /></div>
  return <div className="customer-page"><CustomerPageHero eyebrow="Your order" title={<>Make it a<br /><em>table moment.</em></>} text="Review your picks, choose how you want to enjoy them and we will do the rest." image={imageUrls.mutton} /><main className="section cart-page">{!items.length ? <EmptyState title="Your cart is waiting" text="Add a bowl of biryani and make this a good day." action={<Link to="/menu" className="button button-dark">Explore the menu <Icon name="arrow" size={16} /></Link>} /> : <div className="cart-layout"><div className="cart-items"><div className="cart-heading"><h2>Your picks <span>{items.length} items</span></h2><Link to="/menu" className="text-link">Add more <Icon name="plus" size={15} /></Link></div>{items.map(({ dish, qty }) => <div className="cart-item" key={dish.id}><img src={dish.image} alt={dish.name} /><div className="cart-item-main"><span>{dish.category}</span><h3>{dish.name}</h3><small>{sampleMoney(dish.price)} each</small></div><div className="qty"><button onClick={() => onUpdateQty(dish.id, -1)}>−</button><strong>{qty}</strong><button onClick={() => onUpdateQty(dish.id, 1)}>+</button></div><strong className="cart-line-total">{money(dish.price * qty)}</strong><button className="icon-button" onClick={() => onRemove(dish.id)} aria-label={`Remove ${dish.name}`}><Icon name="trash" size={17} /></button></div>)}<div className="cart-sample-note">* Placeholder prices shown for prototype review only.</div></div><form className="checkout-card" onSubmit={submit}><div className="checkout-head"><Eyebrow>Almost there</Eyebrow><h2>Make it yours.</h2></div><label>Your name<input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Riya Sharma" /></label><label>Phone number<input required value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="10-digit phone number" /></label><div className="choice-group"><span>Enjoy it as</span><div className="choice-row">{["Takeaway", "Dine-in"].map((mode) => <button type="button" key={mode} className={form.mode === mode ? "choice-active" : ""} onClick={() => setForm({ ...form, mode })}>{mode}</button>)}</div></div><div className="choice-group"><span>Payment preference</span><div className="payment-list">{["UPI", "Cash on Delivery", "Card"].map((payment) => <label key={payment} className={form.payment === payment ? "payment-active" : ""}><input type="radio" name="payment" value={payment} checked={form.payment === payment} onChange={() => setForm({ ...form, payment })} /><span className="radio-dot" />{payment}<small>UI only</small></label>)}</div></div><div className="checkout-total"><span>Sample total</span><strong>{money(cartTotal)}</strong></div><Button type="submit" className="full-button">Place sample order <Icon name="arrow" size={16} /></Button><p className="checkout-disclaimer">No real payment is processed. WhatsApp ordering integration is a placeholder in this prototype.</p></form></div>}</main><Footer settings={store.settings} /></div>
}

function EmptyState({ title, text, action }) { return <div className="empty-state"><div className="empty-icon"><Icon name="cart" size={24} /></div><h2>{title}</h2><p>{text}</p>{action}</div> }

